import{_ as s,H as e,f as t,i as n}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"Design（설계）","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/design.md","filePath":"ko/skills/design.md"}'),i={name:"ko/skills/design.md"};function o(l,a,p,d,c,r){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="design-설계" tabindex="-1">Design（설계） <a class="header-anchor" href="#design-설계" aria-label="Permalink to &quot;Design（설계）&quot;">​</a></h1><p><strong>Gate:</strong> 사용자가 명세를 승인할 때까지 코드 없음.</p><p>무엇을 만들어야 할지 알 때까지 한 번에 하나씩 질문한다. 2~3가지 접근 방식과 트레이드오프를 제안하고 하나를 추천한다. 그런 다음 명세를 작성한다.</p><h2 id="명세-결정-목록" tabindex="-1">명세 = 결정 목록 <a class="header-anchor" href="#명세-결정-목록" aria-label="Permalink to &quot;명세 = 결정 목록&quot;">​</a></h2><p>명세는 이 변경에 대한 미해결 질문에 답한다. 일반적인 것들:</p><ul><li>계약 / 인터페이스?</li><li>데이터 형태?</li><li>실패 모드?</li><li>범위 외?</li><li>무엇으로 테스트할 것인가?</li><li>아키텍처?</li></ul><p>관용적으로 명세를 작성한다.</p><p><strong>질문 없음 → 섹션 없음</strong>. Risks / Non-goals가 비어있으면 채우지 않는다.</p><p>선언을 사용하고, 서술은 사용하지 않는다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>contract:  &lt;인터페이스&gt;</span></span>
<span class="line"><span>invariant: &lt;무엇이 성립해야 하는가&gt;</span></span>
<span class="line"><span>test:      &lt;어떻게 알 것인가&gt;</span></span>
<span class="line"><span>deferred:  &lt;지금은 결정 안 함&gt;</span></span></code></pre></div><p>코드는 경로로 참조하고, 절대 붙여넣지 않는다.</p><p>인계 전에 구현에 영향을 미치는 결정만 닫는다: 계약, 데이터, 실패, 테스트. 미해결된 <code>Working notes</code>는 결정, <code>deferred</code>, 또는 질문이 된다.</p><h2 id="_2계층-1파일-docs-staging-specs-yyyy-mm-dd-topic-md" tabindex="-1">2계층, 1파일: <code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code> <a class="header-anchor" href="#_2계층-1파일-docs-staging-specs-yyyy-mm-dd-topic-md" aria-label="Permalink to &quot;2계층, 1파일: \`docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md\`&quot;">​</a></h2><ul><li>상단: 결정, 계약, 불변 조건 (영구적).</li><li><code>## Working notes</code>: 초안, 미해결 질문 (<code>ship</code> 시 삭제).</li></ul><h2 id="roadmap-범위가-≥3-마일스톤에-걸치는-경우" tabindex="-1">Roadmap (범위가 ≥3 마일스톤에 걸치는 경우) <a class="header-anchor" href="#roadmap-범위가-≥3-마일스톤에-걸치는-경우" aria-label="Permalink to &quot;Roadmap (범위가 ≥3 마일스톤에 걸치는 경우)&quot;">​</a></h2><p>한 번에 전부 계획하기엔 너무 클 때 명세에 <code>## Roadmap</code> 추가:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Roadmap</span></span>
<span class="line"><span>- [ ] M1: &lt;한 줄 목표&gt;  ← 지금 상세 계획</span></span>
<span class="line"><span>- [ ] M2: &lt;한 줄 목표&gt;  ← stub</span></span>
<span class="line"><span>- [ ] M3: &lt;한 줄 목표&gt;  ← stub</span></span></code></pre></div><p>마커는 필수다. 현재 마일스톤에 <code>← 지금 상세 계획</code>, 나머지는 모두 <code>← stub</code>. 스텁은 의도이지 약속이 아니다. 전개 전에 업데이트한다.</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code>가 디스크에 존재하고 사용자가 확인한 후 <code>plan</code>에 인계한다.</p><p>두 가지 출구 중 하나:</p><ul><li><strong>→ design</strong>: 방향이 해결해야 할 문제 → <code>plan</code>으로 상세 작업.</li><li><strong>→ archive</strong>: 방향이 지식 산출물 (역공학 발견, 프로토콜 명세), 직접 아카이브.</li></ul>`,22)])])}const u=s(i,[["render",o]]);export{h as __pageData,u as default};
